-- V274: "Connect a Device" guided templates -- new `device` category.
-- Organized by CONNECTION TYPE (protocol + transport), not by device brand
-- or model -- a device picks whichever type template matches what its own
-- setup screen offers, with no new template needed per vendor/model. Pure
-- data on the existing interface_templates table (V67/V92) -- no schema
-- change.
--
-- One real, working template today: "HL7 over TCP/IP". It reuses the
-- already-built, already-tested tcp_mllp_inbound host-query/ack mechanism
-- (services/connectors/tcp_mllp_inbound.go) and the exact DSR^Q03-answering
-- mechanism proven working against a real mock analyzer this session
-- (QRD.8 sample-ID parsing via the real enhancedSegments.QRD.Fields[].Key/
-- .Value shape ParseToJSON produces).
--
-- "ASTM over Serial Port" and "ASTM over TCP/IP" are deliberately NOT
-- created as templates here -- no serial connector and no ASTM engine
-- exist anywhere in this codebase today (confirmed via direct grep), so a
-- clickable template for either would not actually work end to end. Named
-- as a future gap in this template's own guide text instead of shipped as
-- a non-functional placeholder.
--
-- Honest limitation, not silently hidden: the "Derive Order Lookup" step
-- below is a PLACEHOLDER -- it always reports "no pending order found" so a
-- real instrument gets a valid, well-formed DSR^Q03 reply instead of
-- hanging, but it does not call a real HIS. A real bidirectional
-- deployment needs this step replaced with (or followed by) a real lookup
-- against the customer's own HIS order API -- that contract can't be known
-- ahead of time (same "HIS side deliberately left open" decision as the
-- rest of this device-integration plan). The wizard still collects the HIS
-- lookup URL as an optional field so the integrator has somewhere to plug
-- it in.
--
-- Port number (6612) is deliberately inside the real, Docker-mapped
-- TCP/MLLP range (docker-compose.yml: "6610-6670:6610-6670") -- editable by
-- the user at wizard time, but must default to something actually reachable
-- in this deployment, not an arbitrary unmapped port.
--
-- This file is generated by scratchpad/gen_v274.js (not hand-escaped) to
-- avoid the real, easy-to-get-wrong triple-escaping risk of JS script
-- content -> JSON string -> SQL string literal.

INSERT INTO interface_templates
    (id, name, slug, description, category, subcategory, tags, icon, difficulty,
     source_connector_type, source_config_template,
     target_connector_type, target_config_template,
     pipeline_config, message_type,
     required_connection_fields, sanitized_fields, preview_steps,
     estimated_setup_minutes, is_system, is_public, author, usage_count)
VALUES

-- HL7 over TCP/IP — any network-connected HL7 v2 lab instrument
