    'device',
    'network',
    ARRAY['hl7v2','tcp-mllp','network','tcp-ip','bidirectional','lab-instrument'],
    '🔌',
    'beginner',
    'tcp_mllp_inbound',
    '{"host":"0.0.0.0","port":6612,"ack":{"mode":"immediate","on_error":"suppress"},"host_query":{"enabled":false,"message_types":["QRY"],"pipeline_message_type":"QRY"}}',
    'http_outbound',
    '{"method":"POST","content_type":"application/fhir+json","auth_type":"bearer","timeout_seconds":30}',
    '{"execution_groups":[{"sequence":5,"steps":[{"step_name":"TCP/MLLP Inbound (HL7 v2)","step_type":"connector.inbound","sequence":5,"config":{"connectorType":"tcp_mllp_inbound","config":{"host":"0.0.0.0","port":6612,"max_connections":5,"ack":{"mode":"immediate","on_error":"suppress","sending_app":"ezHealthKonnect","sending_facility":"EHK","text_success":"Message received successfully","text_error":"Message processing error"},"host_query":{"enabled":false,"message_types":["QRY"],"pipeline_message_type":"QRY","timeout_seconds":10,"on_failure_nack":true}},"timeoutMs":30000},"enabled":true,"required":true}]},{"sequence":10,"steps":[{"step_name":"Validate HL7 ORU","step_type":"enrichment.validation","sequence":10,"config":{"format":"hl7v2","required_segments":["MSH","PID","OBR","OBX"],"fail_on_error":false},"enabled":true,"required":false}]},{"sequence":20,"steps":[{"step_name":"HL7 → FHIR Transform (ORU^R01)","step_type":"hl7_fhir_transform","sequence":20,"config":{"message_type":"ORU^R01","target_resources":["Observation","DiagnosticReport","Patient"],"include_metadata":true},"enabled":true,"required":true}]},{"sequence":30,"steps":[{"step_name":"Validate FHIR Bundle","step_type":"enrichment.validation","sequence":30,"config":{"format":"fhir_r4","fail_on_error":false},"enabled":true,"required":false}]},{"sequence":200,"steps":[{"step_name":"Derive Order Lookup","step_alias":"derive_order_lookup","step_type":"enrichment.script","sequence":200,"config":{"script":"// PLACEHOLDER: replace with a real lookup against your HIS before relying\n// on bidirectional/host-query mode in production. This stub always reports\n// \"no pending order found\" so the instrument still gets a valid, well-formed\n// reply instead of hanging or erroring -- it never fabricates real order\n// data. Only runs its real logic when host_query.enabled is on and the\n// inbound message is the instrument''s own QRY^Q02 order query (harmless\n// no-op otherwise since nothing downstream of a normal ORU result reads\n// its output).\nvar msg = input.message || input;\nvar qrd = (msg.enhancedSegments && msg.enhancedSegments.QRD) || {};\nvar fields = qrd.Fields || [];\nvar sampleField = fields.filter(function(f) { return f.Key === ''QRD.8''; })[0];\nvar sampleId = sampleField ? sampleField.Value : '''';\n\n({ sample_id: sampleId, test_code: ''UNKNOWN'', test_name: ''No pending order found -- connect this step to your HIS to enable real order lookup'' });"},"enabled":true,"required":false}]},{"sequence":210,"steps":[{"step_name":"Build DSR Reply","step_alias":"build_dsr_reply","step_type":"hl7.build","sequence":210,"config":{"messageType":"DSR","triggerEvent":"Q03","version":"2.5.1","segments":[{"segment":"QAK","cardinality":"single","fields":[{"fieldKey":"QAK.1","literalValue":"Q001"},{"fieldKey":"QAK.2","literalValue":"AA"}]},{"segment":"DSP","cardinality":"single","fields":[{"fieldKey":"DSP.1","literalValue":"1"},{"fieldKey":"DSP.2","sourcePath":"steps.derive_order_lookup.step_output.sample_id"},{"fieldKey":"DSP.3","sourcePath":"steps.derive_order_lookup.step_output.test_code"},{"fieldKey":"DSP.4","sourcePath":"steps.derive_order_lookup.step_output.test_name"}]}]},"enabled":true,"required":false}]},{"sequence":295,"steps":[{"step_name":"Deliver Results to HIS","step_type":"connector.outbound","sequence":295,"config":{"connectorType":"http_outbound","config":{"method":"POST","content_type":"application/fhir+json","auth_type":"bearer","timeout_seconds":30},"contentField":"fhirBundle","contentType":"application/fhir+json"},"enabled":true,"required":true}]}]}',
    'ORU^R01',
    '[{"section":"source","field":"port","label":"Port Number","type":"number","hint":"The network port this server listens on. Enter this same number into the instrument''s own LIS/host communication settings.","required":true},{"section":"source","field":"host_query.enabled","label":"Does this instrument ask for the order before running a test?","type":"boolean","hint":"Turn on for bidirectional mode (the instrument queries for pending orders before processing a sample). Leave off for one-way result reporting only.","required":false},{"section":"target","field":"endpoint","label":"Results Delivery API URL","type":"url","hint":"Where completed lab results are sent, e.g. https://your-his.example.org/api/results","required":true},{"section":"target","field":"bearer_token","label":"Bearer Token","type":"password","hint":"Authorization token for your HIS API, if required","required":false},{"section":"target","field":"his_order_lookup_url","label":"Order-Lookup API URL","type":"url","hint":"Only needed if the toggle above is on. Ask your HIS vendor for the endpoint that returns pending orders for a given sample ID.","required":false}]',
    ARRAY['source.port','target.endpoint','target.bearer_token'],
